//! Malayalam inflection, learned from Wiktionary.
//!
//! Generated by morphe from the Kaikki Malayalam dump of 2026-10-03. Do not edit.
//! Every function is total: unknown words are inflected by prediction, and
//! the `_scored` versions give every candidate with a confidence, best first.
//! Variant confidences reflect Wiktionary's listing order, not measured usage.
//!
//! Data: Wiktionary contributors, CC BY-SA 4.0, via kaikki.org.

#![forbid(unsafe_code)]

pub use morphe::{Options, Scored};
use std::sync::OnceLock;

static DATA: &[u8] = include_bytes!("model.bin");

/// The trained model, for dynamic queries.
pub fn model() -> Option<&'static morphe::Model> {
    static MODEL: OnceLock<Option<morphe::Model>> = OnceLock::new();
    MODEL.get_or_init(|| morphe::Model::decode(DATA)).as_ref()
}

fn best(scored: Scored<String>, word: &str) -> String {
    scored.into_iter().next().map_or_else(|| word.split(',').next().unwrap_or(word).trim().to_string(), |x| x.0)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Case {
    Nominative,
    Accusative,
    Dative,
    Sociative,
    Genitive,
    Instrumental,
    Locative,
    Vocative,
}

impl Case {
    pub const ALL: [Self; 8] = [Self::Nominative, Self::Accusative, Self::Dative, Self::Sociative, Self::Genitive, Self::Instrumental, Self::Locative, Self::Vocative];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Number {
    Singular,
    Plural,
}

impl Number {
    pub const ALL: [Self; 2] = [Self::Singular, Self::Plural];
}

/// Settings for systematic choices. `Malayalam::default()` is what the free functions use.
#[derive(Clone, Copy, Debug, Default)]
pub struct Malayalam {
    pub options: Options,
}

impl Malayalam {
    /// Keep stress and similar marks in the output (on by default).
    pub fn marks(mut self, on: bool) -> Self {
        self.options.marks = on;
        self
    }

    /// A noun form.
    pub fn noun_scored(&self, word: &str, case: Case, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (case, number,) {
            (Case::Nominative, Number::Singular,) => Some(0),
            (Case::Nominative, Number::Plural,) => Some(1),
            (Case::Accusative, Number::Singular,) => Some(2),
            (Case::Accusative, Number::Plural,) => Some(3),
            (Case::Dative, Number::Singular,) => Some(4),
            (Case::Dative, Number::Plural,) => Some(5),
            (Case::Sociative, Number::Singular,) => Some(6),
            (Case::Sociative, Number::Plural,) => Some(7),
            (Case::Genitive, Number::Singular,) => Some(8),
            (Case::Genitive, Number::Plural,) => Some(9),
            (Case::Instrumental, Number::Singular,) => Some(10),
            (Case::Instrumental, Number::Plural,) => Some(11),
            (Case::Locative, Number::Singular,) => Some(12),
            (Case::Locative, Number::Plural,) => Some(13),
            (Case::Vocative, Number::Singular,) => Some(14),
            (Case::Vocative, Number::Plural,) => Some(15),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form. The best candidate; the word itself if nothing is known.
    pub fn noun(&self, word: &str, case: Case, number: Number) -> String {
        best(self.noun_scored(word, case, number), word)
    }

    /// Dictionary spelling of a noun (with stress marks where the data has them).
    pub fn noun_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(0, word)).unwrap_or_else(|| word.to_string())
    }

    /// The past verb.
    pub fn verb_past_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(0);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(1, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The past verb. The best candidate; the word itself if nothing is known.
    pub fn verb_past(&self, word: &str) -> String {
        best(self.verb_past_scored(word), word)
    }

    /// Dictionary spelling of a verb (with stress marks where the data has them).
    pub fn verb_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(1, word)).unwrap_or_else(|| word.to_string())
    }

    /// A pron form.
    pub fn pron_scored(&self, word: &str, case: Case, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (case, number,) {
            (Case::Nominative, Number::Singular,) => Some(0),
            (Case::Nominative, Number::Plural,) => Some(1),
            (Case::Accusative, Number::Singular,) => Some(2),
            (Case::Accusative, Number::Plural,) => Some(3),
            (Case::Dative, Number::Singular,) => Some(4),
            (Case::Dative, Number::Plural,) => Some(5),
            (Case::Sociative, Number::Singular,) => Some(6),
            (Case::Sociative, Number::Plural,) => Some(7),
            (Case::Genitive, Number::Singular,) => Some(8),
            (Case::Genitive, Number::Plural,) => Some(9),
            (Case::Instrumental, Number::Singular,) => Some(10),
            (Case::Instrumental, Number::Plural,) => Some(11),
            (Case::Locative, Number::Singular,) => Some(12),
            (Case::Locative, Number::Plural,) => Some(13),
            (Case::Vocative, Number::Singular,) => Some(14),
            (Case::Vocative, Number::Plural,) => Some(15),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(2, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A pron form. The best candidate; the word itself if nothing is known.
    pub fn pron(&self, word: &str, case: Case, number: Number) -> String {
        best(self.pron_scored(word, case, number), word)
    }

    /// Dictionary spelling of a pron (with stress marks where the data has them).
    pub fn pron_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(2, word)).unwrap_or_else(|| word.to_string())
    }

}

